const fingerprint=r=>[r.date,normalize(r.category),normalize(r.exercise),r.set,r.value,normalize(r.unit),normalize(r.note)].join('\u001f');
function csvRecords(text){const matrix=parseCSV(text);if(!matrix.length)throw Error('Datei ist leer');const h=matrix.shift().map(x=>normalize(x).replace(/^\ufeff/,''));const col=(...names)=>names.map(n=>h.indexOf(normalize(n))).find(i=>i>=0)??-1;const indexes=[col('Datum','date'),col('Bereich','Kategorie','category'),col('Übung','Uebung','exercise'),col('Satz','set'),col('Wert','value','count'),col('Einheit','unit'),col('Notiz','note'),col('Eintrag-ID','record-id','id'),col('Einheit-ID','session-id','session')];if(indexes.slice(0,6).some(i=>i<0))throw Error('Unbekannte CSV-Spalten: erwartet Datum, Bereich, Übung, Satz, Wert, Einheit');return matrix.map((r,n)=>{const get=i=>i<0?'':String(r[i]??'').trim();const [date,category,exercise,set,value,unit,note,id,session]=indexes.map(get);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!tabs.includes(category)||!exercise||!Number.isInteger(Number(set))||Number(set)<1||!Number.isFinite(Number(value))||Number(value)<0||!unit)throw Error('Ungültiger Eintrag in Datenzeile '+(n+2));return {date,category,exercise,set:Number(set),value:Number(value),unit,note,id,session}})}
$('csvImport').onchange=async ev=>{const files=Array.from(ev.target.files||[]);if(!files.length)return;let accepted=[],errors=[];for(const file of files){try{accepted.push(...csvRecords(await file.text()))}catch(e){errors.push(file.name+': '+e.message)}}if(!accepted.length){$('mergeReport').textContent='Keine Daten importiert. '+errors.join(' | ');ev.target.value='';return}const existing=rows(),ids=new Set(existing.map(x=>x.id).filter(Boolean)),keys=new Set(existing.map(fingerprint));const planned=[],pendingIds=new Set(),pendingKeys=new Set();let duplicates=0;for(const rec of accepted){const fp=fingerprint(rec);if((rec.id&&(ids.has(rec.id)||pendingIds.has(rec.id)))||keys.has(fp)||pendingKeys.has(fp)){duplicates++;continue}planned.push(rec);pendingKeys.add(fp);if(rec.id)pendingIds.add(rec.id)}if(!planned.length){$('mergeReport').textContent='Keine neuen Einträge. '+duplicates+' Duplikate erkannt.'+(errors.length?' Fehler: '+errors.join(' | '):'');ev.target.value='';return}if(!confirm(planned.length+' neue Trainingssätze aus '+files.length+' Datei(en) hinzufügen? '+duplicates+' Duplikate werden übersprungen.')){ev.target.value='';return}for(const rec of planned){let ex=state.exercises.find(e=>e.category===rec.category&&normalize(e.name)===normalize(rec.exercise)&&e.unit===rec.unit);if(!ex){ex={id:uid(),name:rec.exercise,category:rec.category,sets:Math.max(1,Math.min(20,rec.set)),target:rec.unit==='Sek.'?30:10,unit:rec.unit,note:''};state.exercises.push(ex)}const id=rec.id&&!ids.has(rec.id)?rec.id:uid();ids.add(id);state.logs.push({id,session:rec.session||'csv-'+uid(),date:rec.date,exerciseId:ex.id,exerciseName:rec.exercise,category:rec.category,set:rec.set,count:rec.value,note:rec.note,unit:rec.unit})}render();const report=planned.length+' neue Sätze importiert · '+duplicates+' Duplikate übersprungen'+(errors.length?' · Fehler: '+errors.join(' | '):'');$('mergeReport').textContent=report;message(report);ev.target.value=''};
$('clearHistory').onclick=()=>{if(!state.logs.length){message('Die Trainingshistorie ist bereits leer.');return}if(!confirm('Wirklich ALLE bisherigen Trainingsergebnisse und Einheitsnotizen löschen? Übungen, Übungsnamen und Einstellungen bleiben erhalten. Diese Aktion kann nicht rückgängig gemacht werden.'))return;state.logs=[];render();message('Trainingshistorie gelöscht. Übungen und Einstellungen sind erhalten geblieben.')};$('json').onclick=()=>download('workout-backup-'+today()+'.json',JSON.stringify({...state,timerPresets},null,2),'application/json');$('import').onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(Array.isArray(data)&&data.every(x=>x&&('Datum' in x||'date' in x))){const result=restoreRecordRows(data);message(result.added+' Sätze ergänzt, '+result.skipped+' Duplikate übersprungen.');ev.target.value='';return}if(!Array.isArray(data.exercises)||!Array.isArray(data.logs))throw Error('Ungültige Backup-Struktur');if(!confirm('Backup mit aktuellen Daten zusammenführen? Vorhandene Daten bleiben erhalten.'))return;const imported={exercises:data.exercises.map(e=>({...e,category:tabs.includes(e.category)?e.category:'Handstand',unit:e.unit||'Wdh.',note:e.note||''})),logs:data.logs,sessions:Array.isArray(data.sessions)?data.sessions:[],active:null};state={...state,exercises:[...new Map([...state.exercises,...imported.exercises].map(x=>[x.id,x])).values()],logs:[...new Map([...state.logs,...imported.logs].map(x=>[x.id,x])).values()],sessions:[...new Map([...state.sessions,...imported.sessions].map(x=>[x.id,x])).values()]};if(Array.isArray(data.timerPresets)){timerPresets=data.timerPresets.filter(p=>p&&typeof p.name==='string'&&Array.isArray(p.steps));saveTimerPresets();showTimerPresets()}render();message('Backup importiert.')}catch(err){message('Import fehlgeschlagen: '+err.message)}ev.target.value=''};function renderChart(){const id=$('chartExercise').value;const logs=state.logs.filter(l=>l.exerciseId===id&&Number(l.count)>0);const hasSeconds=logs.some(l=>l.unit==='Sek.');const normalized=l=>comparableValue(l.count,l.unit,hasSeconds&&l.unit==='Min.'&&Number(l.count)>=120);const byDay={};logs.forEach(l=>byDay[l.date]=Math.max(byDay[l.date]||0,normalized(l)));const data=Object.entries(byDay).sort((a,b)=>a[0].localeCompare(b[0])).slice(-12);const all=state.logs.filter(l=>Number(l.count)>0);const dates=new Set(all.map(l=>l.date));const vals=logs.map(normalized);const total=vals.reduce((a,b)=>a+b,0);const best=vals.length?Math.max(...vals):0;const selected=state.exercises.find(e=>e.id===id);const unit=logs.some(l=>l.unit==='Sek.'||l.unit==='Min.')?'Sek.':(selected?.unit||logs[0]?.unit||'');const avg=vals.length?(total/vals.length).toLocaleString('de-DE',{maximumFractionDigits:1}):'–';$('stats').innerHTML=[['Trainingstage',dates.size],['Gespeicherte Sätze',all.length],['Bestwert / Satz',vals.length?best+' '+unit:'–'],['Ø / Satz',vals.length?avg+' '+unit:'–']].map(([label,value])=>'<div class="statcard"><strong>'+esc(value)+'</strong><span>'+esc(label)+'</span></div>').join('');$('recentStats').textContent=data.length>1?'Erster erfasster Tag: '+data[0][0]+' · Letzter erfasster Tag: '+data[data.length-1][0]+' · Änderung des Tagesbestwerts: '+(data[data.length-1][1]-data[0][1]>0?'+':'')+(data[data.length-1][1]-data[0][1])+' '+unit:'';$('chartInfo').textContent=data.length?data.length+' Trainingstage · höchster Satzwert pro Tag ('+unit+')':'Noch keine Messwerte für diese Übung';const svg=$('chart');if(!data.length){svg.innerHTML='<text x="18" y="110" fill="#aab4cb" font-size="17">Nach dem ersten Training erscheint hier dein Verlauf.</text>';return}const max=Math.max(1,...data.map(x=>x[1])),w=450,h=145,base=170,left=20;let out=`<line x1="${left}" y1="${base}" x2="470" y2="${base}" stroke="#66718d"/>`;data.forEach(([date,v],i)=>{const bw=w/data.length,x=left+i*bw+5,bh=h*v/max;out+=`<rect x="${x}" y="${base-bh}" width="${Math.max(6,bw-10)}" height="${bh}" rx="3" fill="#79d7d0"><title>${esc(date)}: ${v}</title></rect><text x="${x+Math.max(6,bw-10)/2}" y="${Math.max(13,base-bh-5)}" fill="#f8d18c" font-size="12" text-anchor="middle">${v}</text>`;if(i===0||i===data.length-1||data.length<=5)out+=`<text x="${x+Math.max(6,bw-10)/2}" y="190" fill="#abb9cf" font-size="11" text-anchor="middle">${date.slice(5)}</text>`});svg.innerHTML=out}$('chartExercise').onchange=renderChart;

