function restoreRecordRows(records){
 if(!Array.isArray(records))throw Error('Die Datei enthält keine Liste von Trainingssätzen.');
 const existingIds=new Set(state.logs.map(x=>x.id));
 const existingKeys=new Set(rows().map(fingerprint));
 const addedSessions=new Set((state.sessions||[]).map(x=>x.id));
 let added=0,skipped=0;
 for(const raw of records){
  const rec={date:raw['Datum']??raw.date,category:raw['Bereich']??raw.category,exercise:raw['Übung']??raw.exercise,set:Number(raw['Satz']??raw.set),value:Number(raw['Wert']??raw.value),unit:raw['Einheit']??raw.unit,note:raw['Notiz']??raw.note??'',id:raw['Eintrag-ID']??raw.id,session:raw['Einheit-ID']??raw.session};
  if(!/^\d{4}-\d{2}-\d{2}$/.test(rec.date)||!tabs.includes(rec.category)||!rec.exercise||!Number.isInteger(rec.set)||rec.set<1||!Number.isFinite(rec.value)||rec.value<0)throw Error('Ungültiger Trainingssatz im Import.');
  if((rec.id&&existingIds.has(rec.id))||existingKeys.has(fingerprint(rec))){skipped++;continue}
  let ex=state.exercises.find(e=>e.category===rec.category&&normalize(e.name)===normalize(rec.exercise)&&e.unit===rec.unit);
  if(!ex){ex={id:uid(),name:rec.exercise,category:rec.category,sets:Math.max(1,rec.set),target:rec.unit==='Wdh.'?10:30,unit:rec.unit,note:'',sort_order:state.exercises.filter(e=>e.category===rec.category).length};state.exercises.push(ex)}
  const id=isUUID(rec.id)?rec.id:uid();const session=isUUID(rec.session)?rec.session:uid();
  state.logs.push({id,session,date:rec.date,exerciseId:ex.id,exerciseName:rec.exercise,category:rec.category,set:rec.set,count:rec.value,unit:rec.unit,note:rec.note});
  if(!addedSessions.has(session)){state.sessions.push({id:session,date:rec.date,started_at:new Date(rec.date+'T12:00:00').toISOString(),finished_at:null});addedSessions.add(session)}
  existingIds.add(id);existingKeys.add(fingerprint(rec));added++;
 }
 render();return {added,skipped};
}
function addRecoveryButton(){
 const anchor=$('import');if(!anchor)return;
 const btn=document.createElement('button');btn.type='button';btn.textContent='📥 Trainingsdaten aus w1.json wiederherstellen';btn.style.margin='8px 0';btn.style.maxWidth='100%';
 btn.onclick=()=>{if(!confirm('Die 54 exportierten Trainingssätze aus w1.json ergänzen? Vorhandene Daten bleiben erhalten; Duplikate werden übersprungen.'))return;try{const r=restoreRecordRows(bundledRecoveryRecords);message(r.added+' Sätze wiederhergestellt, '+r.skipped+' bereits vorhanden. Synchronisierung läuft.');alert(r.added+' Trainingssätze ergänzt; '+r.skipped+' Duplikate übersprungen. Bitte auf die Supabase-Speicherbestätigung warten.')}catch(e){alert('Wiederherstellung fehlgeschlagen: '+e.message)}};
 anchor.parentElement.appendChild(btn);
}
