// Programmierbarer Sequenz-Timer; AudioContext wird direkt durch eine Benutzeraktion entsperrt.
let soundCtx=null;async function unlockSound(){try{soundCtx=soundCtx||new (window.AudioContext||window.webkitAudioContext)();await soundCtx.resume();const buffer=soundCtx.createBuffer(1,1,soundCtx.sampleRate),src=soundCtx.createBufferSource();src.buffer=buffer;src.connect(soundCtx.destination);src.start(0);return true}catch(e){message('Audio konnte nicht aktiviert werden: '+e.message);return false}}
function sound(freq=740){try{if(!soundCtx||soundCtx.state!=='running')return;const osc=soundCtx.createOscillator(),gain=soundCtx.createGain(),t=soundCtx.currentTime;osc.frequency.value=freq;osc.type='sine';gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(.45,t+.015);gain.gain.exponentialRampToValueAtTime(.0001,t+.45);osc.connect(gain).connect(soundCtx.destination);osc.start(t);osc.stop(t+.47)}catch(e){}}
$('soundTest').onclick=async()=>{if(await unlockSound()){sound(900);message('Testton abgespielt. Bitte Lautstärke und Stummmodus prüfen.')}};
let steps=[{name:'Handstand',kind:'work',seconds:40},{name:'Pause',kind:'rest',seconds:20},{name:'Compression',kind:'work',seconds:30},{name:'Pause',kind:'rest',seconds:20}];
function drawSteps(){$('sequenceSteps').innerHTML=steps.map((s,i)=>`<div class="row" style="margin:9px 0;padding:8px;border:1px solid #394057;border-radius:9px"><span class="small">${i+1}.</span><input aria-label="Name" data-si="${i}" data-key="name" value="${esc(s.name)}" style="flex:2;min-width:120px"><select data-si="${i}" data-key="kind"><option value="work" ${s.kind==='work'?'selected':''}>Übung</option><option value="rest" ${s.kind==='rest'?'selected':''}>Pause</option></select><label class="small">Sek. <input data-si="${i}" data-key="seconds" type="number" min="1" max="3600" value="${s.seconds}"></label><button data-delete="${i}" class="danger">✕</button></div>`).join('')}
$('sequenceSteps').addEventListener('change',e=>{const i=Number(e.target.dataset.si),key=e.target.dataset.key;if(!key||!steps[i])return;steps[i][key]=key==='seconds'?Math.max(1,Math.min(3600,Number(e.target.value)||1)):e.target.value;resetSequence()});$('sequenceSteps').addEventListener('click',e=>{const b=e.target.closest('[data-delete]');if(!b)return;if(steps.length<=1){message('Mindestens eine Sequenz ist erforderlich.');return}steps.splice(Number(b.dataset.delete),1);drawSteps();resetSequence()});$('addStep').onclick=()=>{steps.push({name:'Neue Übung',kind:'work',seconds:30});drawSteps();resetSequence()};
let seq={running:false,index:0,round:1,remaining:40,deadline:0,handle:null,done:false,completed:0};const seqRounds=()=>Math.max(1,Math.min(100,Number($('sequenceRounds').value)||1));function drawSequence(){const step=steps[seq.index]||{name:'Fertig',kind:'work',seconds:1};const kind=seq.done?'done':step.kind==='rest'?'rest':'work';const t=Math.max(0,Math.ceil(seq.remaining));$('sequenceClock').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');$('sequenceClock').className='timer '+kind;const elapsed=seq.done?100:Math.max(0,Math.min(100,(1-seq.remaining/Math.max(1,Number(step.seconds)||1))*100));$('sequenceProgress').className='sequence-progress '+kind;$('sequenceProgressFill').style.width=elapsed.toFixed(1)+'%';$('sequenceProgressFill').style.backgroundColor=kind==='rest'?'#70e6a4':kind==='done'?'#9dc4ff':'#ffd45f';$('sequenceClock').style.color=kind==='rest'?'#70e6a4':kind==='done'?'#9dc4ff':'#ffd45f';$('sequenceProgress').setAttribute('aria-valuenow',String(Math.round(elapsed)));const cycleSeconds=steps.reduce((sum,item)=>sum+Math.max(1,Number(item.seconds)||1),0);const totalSeconds=cycleSeconds*seqRounds();const phaseSeconds=Math.max(1,Number(step.seconds)||1);const completedSeconds=seq.done?totalSeconds:seq.completed+Math.max(0,Math.min(phaseSeconds,phaseSeconds-seq.remaining));const totalPercent=totalSeconds?Math.max(0,Math.min(100,100*completedSeconds/totalSeconds)):0;const overallProgress=$('sequenceTotalProgress');overallProgress.value=totalPercent;overallProgress.setAttribute('aria-valuenow',String(Math.round(totalPercent)));$('sequenceTotalProgressText').textContent=Math.round(totalPercent)+' % abgeschlossen';const title=$('sequenceExerciseName'),next=$('sequenceNextExercise');title.textContent=seq.done?'Geschafft!':step.name;title.classList.toggle('is-rest',!seq.done&&step.kind==='rest');if(!seq.done&&step.kind==='rest'){let nextWork=null;for(let offset=1;offset<=steps.length;offset++){const idx=(seq.index+offset)%steps.length;const wraps=seq.index+offset>=steps.length;if(wraps&&seq.round>=seqRounds())break;if(steps[idx]?.kind==='work'){nextWork=steps[idx];break}}next.hidden=false;next.textContent=nextWork?'Als Nächstes: '+nextWork.name:'Anschließend: Fertig!'}else{next.hidden=true;next.textContent=''};$('sequencePhase').textContent=seq.done?'Fertig!':`${step.kind==='rest'?'Pause':'Übung'} · Schritt ${seq.index+1}/${steps.length} · Durchlauf ${seq.round}/${seqRounds()}${seq.running?' · läuft':' · pausiert'}`}
function pauseSequence(){if(seq.running)seq.remaining=Math.max(0,(seq.deadline-Date.now())/1000);seq.running=false;clearInterval(seq.handle);seq.handle=null;drawSequence()}
function resetSequence(){pauseSequence();seq.index=0;seq.round=1;seq.done=false;seq.completed=0;seq.remaining=steps[0].seconds;drawSequence()}
function sequenceTick(){if(!seq.running)return;let remaining=(seq.deadline-Date.now())/1000;while(remaining<=0&&!seq.done){seq.completed+=Math.max(1,Number(steps[seq.index].seconds)||1);sound(steps[seq.index].kind==='rest'?650:950);if(seq.index===steps.length-1){if(seq.round>=seqRounds()){seq.done=true;seq.running=false;clearInterval(seq.handle);seq.handle=null;sound(1100);break}seq.index=0;seq.round++}else seq.index++;remaining+=steps[seq.index].seconds}seq.remaining=seq.done?0:remaining;if(!seq.done)seq.deadline=Date.now()+remaining*1000;drawSequence()}
$('sequenceStart').onclick=async()=>{await unlockSound();if(seq.running)return;if(seq.done)resetSequence();sound(900);seq.running=true;seq.deadline=Date.now()+seq.remaining*1000;seq.handle=setInterval(sequenceTick,150);drawSequence()};$('sequencePause').onclick=pauseSequence;$('sequenceReset').onclick=resetSequence;$('sequenceRounds').onchange=resetSequence;document.addEventListener('visibilitychange',()=>{if(!document.hidden&&seq.running)sequenceTick()});drawSteps();resetSequence();

