function saveTimerPresets(){window.workoutBridge?.changed();try{localStorage.setItem(TIMER_KEY,JSON.stringify(timerPresets))}catch{message('Timer konnten nicht gespeichert werden.')}}
function showTimerPresets(){const selected=$('presetSelect').value;$('presetSelect').innerHTML='<option value="">Bitte auswählen</option>'+timerPresets.map((p,i)=>`<option value="${i}">${esc(p.name)}</option>`).join('');if(timerPresets[selected])$('presetSelect').value=selected}
$('savePreset').onclick=async()=>{const name=$('presetName').value.trim();if(!name){message('Bitte einen Namen für den Timer eingeben.');return}const preset={id:crypto.randomUUID(),name,rounds:seqRounds(),steps:steps.map(x=>({...x}))};const index=timerPresets.findIndex(p=>p.name.toLocaleLowerCase('de-DE')===name.toLocaleLowerCase('de-DE'));if(index>=0&&!confirm('Gespeicherten Timer „'+name+'“ überschreiben?'))return;if(index>=0){preset.id=timerPresets[index].id||crypto.randomUUID();timerPresets[index]=preset}else timerPresets.push(preset);saveTimerPresets();showTimerPresets();$('presetSelect').value=String(index>=0?index:timerPresets.length-1);message('Timer „'+name+'“ lokal gespeichert; übertrage nach Supabase …');try{await window.workoutSaveTimer(preset);message('✓ Timer „'+name+'“ in Supabase gespeichert.')}catch(err){message('⚠ Timer nur lokal gespeichert: '+err.message+' — bitte erneut speichern.')}};
$('loadPreset').onclick=()=>{const i=Number($('presetSelect').value);if($('presetSelect').value===''||!timerPresets[i]){message('Bitte einen gespeicherten Timer auswählen.');return}const p=timerPresets[i];steps=p.steps.map(x=>({...x}));$('sequenceRounds').value=p.rounds;$('presetName').value=p.name;drawSteps();resetSequence();message('Timer „'+p.name+'“ geladen.')};
$('deletePreset').onclick=async()=>{const i=Number($('presetSelect').value);if($('presetSelect').value===''||!timerPresets[i])return;if(!confirm('Gespeicherten Timer „'+timerPresets[i].name+'“ löschen?'))return;const removed=timerPresets[i];try{if(window.workoutDeleteTimer)await window.workoutDeleteTimer(removed.id)}catch(e){message('Löschen in Supabase fehlgeschlagen: '+e.message);return}timerPresets.splice(i,1);saveTimerPresets();showTimerPresets();message('Timer in den Papierkorb verschoben.')};timerPresets.forEach(p=>{if(!p.id)p.id=crypto.randomUUID()});window.workoutBridge?.setTimers(()=>timerPresets);showTimerPresets();
$('refreshPresets').onclick=async()=>{try{const cloud=await window.workoutBridge.refreshTimers();timerPresets=cloud.filter(p=>!p.deleted_at);saveTimerPresets();showTimerPresets();message(timerPresets.length+' aktive Timer aus Supabase geladen.');if(!$('timerTrash').hidden)await renderTimerTrash()}catch(e){message('Timer konnten nicht geladen werden: '+e.message)}};
async function renderTimerTrash(){try{const deleted=await window.workoutTrashTimers();const target=$('timerTrashItems');target.replaceChildren();if(!deleted.length){target.textContent='Papierkorb ist leer.';return}for(const item of deleted){const row=document.createElement('div');row.className='row';row.style.marginBottom='8px';const label=document.createElement('span');label.textContent=item.name+' · gelöscht '+new Date(item.deleted_at).toLocaleString('de-DE');const button=document.createElement('button');button.textContent='Wiederherstellen';button.onclick=async()=>{try{await window.workoutRestoreTimer(item.id);const cloud=await window.workoutBridge.refreshTimers();timerPresets=cloud.filter(p=>!p.deleted_at);saveTimerPresets();showTimerPresets();await renderTimerTrash();message('Timer wiederhergestellt.')}catch(e){message('Wiederherstellung fehlgeschlagen: '+e.message)}};row.append(label,button);target.append(row)}}catch(e){message('Papierkorb konnte nicht geladen werden: '+e.message)}}
