const sortedChoices=[...choices.entries()].sort(([ka,a],[kb,b])=>categoryIndex(a)-categoryIndex(b)||(orderIndex.get(ka)??999999)-(orderIndex.get(kb)??999999)||a.name.localeCompare(b.name,'de'));
