hosen?`${points.length} Trainingstage · Rekord ${Math.max(0,...byDate.values())} ${unit} · bester einzelner Satz je Tag`:'Wähle eine Übung aus, um deren Bestwerte über die Zeit zu sehen.';const svg=$('statsChart');if(!points.length){svg.innerHTML='<text x="20" y="110" fill="#aab4cb" font-size="16">'+(chosen?'Für diese Übung liegen keine Daten vor.':'Bitte eine Übung auswählen.')+'</text>'}else{const max=Math.max(1,...points.map(p=>p[1]));const xy=points.map(([d,v],i)=>[30+i*420/Math.max(1,points.length-1),185-v/max*145,d,v]);svg.innerHTML='<line x1="25" y1="185" x2="460" y2="185" stroke="#66718d"/>'+(xy.length>1?`<polyline points="${xy.map(p=>p[0]+','+p[1]).join(' ')}" stroke="#7bd8d0" stroke-width="3" fill="none"/>`:'')+xy.map(([x,y,d,v],i)=>`<circle cx="${x}" cy="${y}" r="5" fill="#7bd8d0"><title>${esc(d)}: ${v} ${esc(unit)}</title></circle>${(i===0||i===xy.length-1||xy.length<=7)?`<text x="${x}" y="208" fill="#b7c4dc" font-size="11" text-anchor="middle">${d.slice(5)}</text>`:''}<text x="${x}" y="${Math.max(12,y-12)}" fill="#ffcf86" font-size="11" text-anchor="middle">${v}</text>`).join('')}
